import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem72 protege identidade operação e idempotência',()=>{for(const [id,titulo] of [['EbNVkHXOor6py78Wgl8X','Tripé Inteligente 1.8m com Rastreamento Facial AI Estável 360° para Celular、Câmera、Vlog E Gopro, Basike Tripé Celular Profissional Universal Bastão Selfie Com Controle Remoto Bluetooth'],['eFH6DoZM48JWTDwQIImg','Kit 2 Refil Ntk Gás Butano + Maçarico Camping Fogareiro 227g'],['ERUkcWCy7XxGVEyDizZ2','Controlador Gamesir Galileo G8 Plus Com Bluetooth Para Cel']]){const p={id,titulo,preco:'preservado',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Capa para '+titulo,comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/diversão garantida|estabilidade garantida|inclui fogareiro|compatibilidade universal/i);}});
